#!/usr/bin/env bash
# apply-floor-deck.sh · EcoWoods
# Upgrades the Floor Catalog from a scrolling mosaic into a swipeable card DECK
# (Tinder/Bumble-style: drag to fling, arrows/dots to browse, tap for the
# 3-photo + spec lightbox). Hand-rolled Pointer Events + CSS transforms — no
# external library, matching the existing SwipeDeck engine. Idempotent.
#
# Prereq: apply-floor-catalog.sh already run (component, data, images present).
set -euo pipefail
[[ -f pnpm-workspace.yaml && -d apps/web ]] || { echo "✗ run from repo root"; exit 1; }
APP=apps/web/app
[[ -f "$APP/components/FloorCatalog.tsx" ]] || { echo "✗ run apply-floor-catalog.sh first"; exit 1; }

echo "▸ Installing swipeable deck component"
base64 -d > "$APP/components/FloorCatalog.tsx" <<'B64_COMP'

B64_COMP

echo "▸ Swapping catalog CSS for deck CSS"
CSS_TMP=$(mktemp)
base64 -d > "$CSS_TMP" <<'B64_CSS'

B64_CSS
node - "$APP/globals.css" "$CSS_TMP" <<'NODE'
const fs=require('fs'); const [g,c]=process.argv.slice(2);
let s=fs.readFileSync(g,'utf8'); const block=fs.readFileSync(c,'utf8').trim();
// remove the redundant standalone CTA block (button now lives in the deck)
s=s.replace(/\n?\/\* === EW:FLOOR-CATALOG-CTA START === \*\/[\s\S]*?\/\* === EW:FLOOR-CATALOG-CTA END === \*\/\n?/g,'\n');
// replace the main catalog block
if(s.includes('/* === EW:FLOOR-CATALOG START === */')){
  s=s.replace(/\/\* === EW:FLOOR-CATALOG START === \*\/[\s\S]*?\/\* === EW:FLOOR-CATALOG END === \*\//, block);
} else {
  if(!s.endsWith('\n')) s+='\n';
  s+='\n'+block+'\n';
}
fs.writeFileSync(g,s);
console.log('  → deck CSS present:', s.includes('.fc-stack'));
console.log('  → old CTA block removed:', !s.includes('EW:FLOOR-CATALOG-CTA'));
NODE
rm -f "$CSS_TMP"
echo "✅ Deck installed. Restart dev:  pnpm --filter web dev"
